window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[125]={"id":"125","numero":125,"titre":"Troubles de la miction et incontinence urinaire","objectifs":[{"id":"125-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition des symptômes du bas appareil urinaire SBAU (= LUTS anglosaxon) (examen clinique, démarche diagnostique)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\"><strong>symptômes du bas appareil urinaire (SBAU)</strong></span> (<em>LUTS — Lower Urinary Tract Symptoms</em>) sont à <strong>préférer</strong> aux termes « troubles urinaires fonctionnels » ou « troubles mictionnels ». Ils sont classés selon la <span class=\"kw-def\">phase du cycle mictionnel</span> durant laquelle ils surviennent.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe d'interrogatoire</strong>\n        <ul>\n          <li>Il faut <strong>tous</strong> <span class=\"kw-clinique\">les</span> rechercher chez un patient, <span class=\"kw-clinique\">même si un seul symptôme prédomine</span>.</li>\n          <li>Leur terminologie est <span class=\"kw-clinique\">précise</span> — chaque mot a une définition.</li>\n        </ul>\n      </div>\n      <table >\n        <thead><tr><th>Phase</th><th>Symptômes et définitions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Stockage / remplissage</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Incontinence urinaire</span> : fuite involontaire d'urine.</li>\n                <li><span class=\"kw-clinique\">Énurésie</span> : miction <strong>complète involontaire</strong> (nocturne durant le sommeil, ou diurne lors d'un paroxysme émotionnel).</li>\n                <li><span class=\"kw-clinique\">Pollakiurie</span> : augmentation du nombre de mictions à diurèse constante — <span class=\"kw-chiffre\">≥ 8 mictions/24 h</span> le jour ; nocturne dès <span class=\"kw-chiffre\">≥ 1 lever</span> si gênant.</li>\n                <li><span class=\"kw-clinique\">Nycturie</span> : être <strong>réveillé par l'envie d'uriner</strong> — anormale dès le <span class=\"kw-chiffre\">1ᵉʳ lever</span> s'il entraîne une gêne.</li>\n                <li><span class=\"kw-clinique\">Urgenturie</span> : désir soudain, impérieux et irrépressible d'uriner — « le besoin dérange, l'urgenturie surprend ».</li>\n                <li><span class=\"kw-clinique\">Syndrome clinique d'hyperactivité vésicale (SCHV)</span> : centré sur l'urgenturie (sa seule présence suffit), ± pollakiurie / nycturie / incontinence.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Vidange (mictionnelle)</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Brûlures mictionnelles</span> : ressenties dans l'urètre au passage de l'urine.</li>\n                <li><span class=\"kw-clinique\">Syndrome dysurique (dysurie)</span> = <span class=\"kw-chiffre\">≥ 1</span> des signes : retard au démarrage, nécessité de pousser, jet faible et/ou en arrosoir, jet interrompu, miction en plusieurs temps.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Post-mictionnelle</strong></span></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Gouttes retardataires</span> ;</li>\n                <li><span class=\"kw-clinique\">Sensation de vidange incomplète</span> (peuvent s'intégrer au syndrome dysurique).</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Rappel physiologique — continence <span class=\"kw-bio\">vs</span> miction</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Continence</span> : tonus <span class=\"kw-ttt\">sympathique</span> → contraction du sphincter lisse + inhibition du détrusor.</li>\n          <li><span class=\"kw-clinique\">Miction</span> : levée de l'inhibition pontique → ↓ sympathique (relâche le sphincter lisse) + ↑ <span class=\"kw-ttt\">parasympathique</span> (contracte le détrusor) + relaxation du sphincter strié (nerf pudendal).</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale · 51 — Troubles mictionnels de l'enfant · 130 — Personne âgée malade</em></p>","frequence":1},{"id":"125-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l'incontinence urinaire","contenu":"<p>L'<span class=\"kw-def\"><strong>incontinence urinaire (IU)</strong></span> est une <span class=\"kw-def\">perte involontaire d'urine</span>.</p>\n      <div class=\"obj-callout success\">\n        <strong>Enjeu — une maladie « à elle seule »</strong>\n        <ul>\n          <li>C'est un <span class=\"kw-clinique\">problème social ou d'hygiène</span> : l'IU est le plus souvent <strong>la maladie à elle seule</strong>.</li>\n          <li>Elle <span class=\"kw-alerte\">altère profondément la qualité de vie</span>… <strong>sans menacer la survie</strong> du patient.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade</em></p>","frequence":0},{"id":"125-3","rang":"B","rubrique":"Définition","titre":"Connaître les types d'incontinence (homme et femme)","contenu":"<p>Trois grands types principaux, puis des formes particulières à connaître.</p>\n      <div class=\"callout callout-info\">\n        <strong>Incontinence urinaire d'effort (IUE)</strong> — <span class=\"kw-clinique\">pathologie presque exclusivement féminine</span>\n        <ul>\n          <li><span class=\"kw-etio\">Mécanismes</span> : hypermobilité urétrale par défaut de soutènement (F), incompétence sphinctérienne (F, H).</li>\n          <li><span class=\"kw-clinique\">Contexte</span> : effort physique, <span class=\"kw-clinique\">toux</span>, éternuements, marche, port de charges lourdes, rires.</li>\n          <li><span class=\"kw-clinique\">Arrêt</span> au repos ou pendant le sommeil.</li>\n          <li><strong>Signe négatif clé</strong> : <span class=\"kw-clinique\">jet non précédé de besoin</span>.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Incontinence urinaire par urgenturie (IUU)</strong>\n        <ul>\n          <li>Fuite de <strong>plus grande quantité</strong> (vidange complète) <span class=\"kw-clinique\">précédée / accompagnée d'une urgenturie</span>.</li>\n          <li><span class=\"kw-clinique\">Contexte</span> : survient <strong>n'importe quand</strong> (effort, repos, jour, nuit).</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Incontinence urinaire mixte (IUM)</strong>\n        <ul>\n          <li>Association <span class=\"kw-clinique\">effort + urgenturie</span>.</li>\n        </ul>\n      </div>\n      <p><strong>Autres types d'incontinence urinaire</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">IU fonctionnelle</span> : bas appareil normal mais difficulté cognitive / de mouvement empêchant d'atteindre <span class=\"kw-clinique\">les</span> toilettes.</li>\n        <li><span class=\"kw-def\">IU multifactorielle</span> : facteurs du bas appareil + facteurs extra-urinaires (polymédication, âge, environnement…).</li>\n        <li><span class=\"kw-def\">IU continue / permanente</span> : perte involontaire continue d'urine.</li>\n        <li><span class=\"kw-def\">IU insensible</span> : perte que le patient ne ressent pas.</li>\n        <li><span class=\"kw-def\">IU coïtale</span> (femme) : perte durant un rapport (à l'orgasme ou à la pénétration).</li>\n        <li><span class=\"kw-def\">IU associée à une fistule</span> : fuites par un orifice anormal, en particulier vaginal.</li>\n        <li><span class=\"kw-def\">IU posturale</span> : au changement de position (assis → debout).</li>\n        <li><span class=\"kw-def\">IU par regorgement</span> (rétention chronique) : <span class=\"kw-chiffre\">résidu post-mictionnel &gt; 300 mL</span>, <span class=\"kw-clinique\">vessie palpable et indolore</span> après la miction.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 50 — Pathologie génito-scrotale · 310 — Tumeurs de la prostate · 130 — Personne âgée malade</em></p>","frequence":2},{"id":"125-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d'une incontinence urinaire d'effort (IUE) et d'une incontinence urinaire sur urgenturies (IUU), leur quantification et leur retentissement","contenu":"<div class=\"obj-callout success\">Le diagnostic d'incontinence urinaire est <strong>avant tout clinique</strong> : il repose sur l'<span class=\"kw-clinique\">interrogatoire</span> et l'<span class=\"kw-clinique\">examen clinique</span>.</div>\n      <p><strong>Interrogatoire — identifier et typer la fuite</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">IUE</span> : fuite <strong>non précédée de besoin</strong>, survenant à l'effort.</li>\n        <li><span class=\"kw-clinique\">IUU</span> : fuite précédée d'urgenturie, jour <strong>et</strong> nuit.</li>\n        <li><span class=\"kw-clinique\">IU permanente / insensible</span> : aucune sensation de besoin ni de passage d'urine.</li>\n        <li><span class=\"kw-clinique\">IU sur rétention chronique</span> : coexistence de SBAU de la phase de vidange.</li>\n        <li><span class=\"kw-alerte\">Troubles anorectaux / génitosexuels associés</span> → suspecter une cause neurologique.</li>\n      </ul>\n      <p><strong>Examen clinique — « voir la fuite »</strong> (objectif n°1)</p>\n      <ul>\n        <li>Examen <span class=\"kw-clinique\">vessie pleine</span>, en reproduisant <span class=\"kw-clinique\">les</span> circonstances (homme : décubitus puis debout ; femme : position gynécologique puis debout).</li>\n        <li><span class=\"kw-clinique\">Test d'effort</span> : fuite ? mobilité cervico-urétrale ? correction par soutènement ?</li>\n        <li><span class=\"kw-clinique\">Test de soutènement urétral</span> (femme, si IUE par hypermobilité) : positif si l'IUE disparaît à la manœuvre → oriente la <span class=\"kw-ttt\">chirurgie</span> (ex. bandelette sous-urétrale).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Quantification</th><th>Retentissement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Index de Sandvik</span> (fréquence × quantité)</li>\n                <li><span class=\"kw-def\">USP</span> (<em>Urinary Symptoms Profile</em>) : IUE, dysurie, urgenturie</li>\n                <li><span class=\"kw-clinique\">Calendrier mictionnel</span> sur <span class=\"kw-chiffre\">2-3 jours</span></li>\n                <li><span class=\"kw-clinique\">Nombre et type de protections</span></li>\n                <li><span class=\"kw-clinique\">Pad Test</span> (pesée des protections) : évaluation la plus <strong>objective</strong> — optionnel</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Échelle directe <span class=\"kw-chiffre\">0 à 10</span> : « à combien estimez-vous votre gêne ? »</li>\n                <li>Questions indirectes : « <span class=\"kw-clinique\">les</span> fuites vous empêchent de faire quoi ? »</li>\n                <li>Questionnaires de <span class=\"kw-clinique\">qualité de vie</span></li>\n                <li>Attentes du patient et traitements qu'il est prêt à subir</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade</em></p>","frequence":1},{"id":"125-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence avec l'âge de l'IUE de l'IUU et de l'incontinence urinaire mixte (IUM), les facteurs de risque chez l'homme, la femme et le sujet âgé (DIAPPERS)","contenu":"<table >\n        <thead><tr><th></th><th>Femme</th><th>Homme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Fréquence</strong></td>\n            <td><span class=\"kw-chiffre\">5-15 %</span> entre <span class=\"kw-chiffre\">40-70 ans</span> ; <span class=\"kw-chiffre\">&gt; 15 %</span> après <span class=\"kw-chiffre\">70 ans</span></td>\n            <td><span class=\"kw-chiffre\">2 à 10× moins fréquente</span> que chez la femme</td>\n          </tr>\n          <tr>\n            <td><strong>Type prédominant</strong></td>\n            <td>IUE jusqu'à <span class=\"kw-chiffre\">≤ 60 ans</span>, puis IUM ou IUU</td>\n            <td>IUU &gt; IUM &gt; IUE</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> chez la femme</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Modifiables</span> : carence hormonale, <span class=\"kw-etio\">sédentarité</span> <em>ou</em> sport intensif, <span class=\"kw-clinique\">toux</span> chronique, <strong><span class=\"kw-etio\">obésité</span></strong> (FR aggravant modifiable le plus important — perte de <span class=\"kw-chiffre\">5 %</span> améliore l'IU).</li>\n        <li><span class=\"kw-etio\">Intrinsèques</span> : âge, ménopause, <span class=\"kw-etio\">génétique</span> (×3 si mère/sœur), ethnie (caucasienne &gt; afro-américaine &gt; asiatique).</li>\n        <li><span class=\"kw-etio\">Gynéco-obstétricaux</span> : <span class=\"kw-ci\">grossesse</span>, accouchement voie basse, travail expulsif, <span class=\"kw-ttt\">chirurgie</span> / <span class=\"kw-clinique\">irradiation</span> pelvienne.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Facteurs de risque</span> chez l'homme</strong> — majoritairement <span class=\"kw-clinique\">non modifiables</span></p>\n      <ul>\n        <li>Âge, SBAU associés, infections urinaires, démence / troubles cognitifs, maladies neurologiques, <span class=\"kw-clinique\">irradiation</span> pelvienne.</li>\n        <li><span class=\"kw-alerte\">Prostatectomie totale / cystoprostatectomie</span> : IU dans <span class=\"kw-chiffre\">2-50 %</span> des cas (souvent <span class=\"kw-etio\">iatrogène</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>DIAPPERS</strong> — IU <span class=\"kw-def\">transitoire et réversible</span> du sujet âgé (« <em>diapers</em> » = couches en anglais)\n        <ul>\n          <li><strong>D</strong> — <span class=\"kw-clinique\">Délirium</span> / confusion (penser à une RAU sous-jacente)</li>\n          <li><strong>I</strong> — <span class=\"kw-etio\">Infection</span> urinaire symptomatique</li>\n          <li><strong>A</strong> — <span class=\"kw-etio\">Atrophie</span> vaginale (carence hormonale)</li>\n          <li><strong>P</strong> — <span class=\"kw-etio\">Psychologique</span> (dépression, anxiété)</li>\n          <li><strong>P</strong> — <span class=\"kw-alerte\">Pharmacologique</span> (polymédication, iatrogénie)</li>\n          <li><strong>E</strong> — <span class=\"kw-etio\">Excès de diurèse</span> (<span class=\"kw-etio\">diabète</span>, <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-clinique\">œdèmes</span>)</li>\n          <li><strong>R</strong> — <span class=\"kw-clinique\">Restriction de mobilité</span> (IU fonctionnelle)</li>\n          <li><strong>S</strong> — <span class=\"kw-clinique\">Selles</span> = <span class=\"kw-clinique\">constipation</span> (IU chez <span class=\"kw-chiffre\">10 %</span> des sujets âgés)</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 130 — Personne âgée malade · 124 — Ménopause - andropause</em></p>","frequence":0},{"id":"125-6","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes physiopathologiques de l'incontinence urinaire d'effort, de l'urgence mictionnelle","contenu":"<p>Tout repose sur un <span class=\"kw-def\">déséquilibre entre les forces de retenue et les forces d'expulsion</span>.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Déséquilibre</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\"><strong>IU d'effort</strong></span></td><td><span class=\"kw-clinique\">Forces de retenue diminuées</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>IU par urgenturie</strong></span></td><td><span class=\"kw-clinique\">Capacité de stockage diminuée + forces d'expulsion augmentées</span></td></tr>\n          <tr><td><span class=\"kw-def\"><strong>IU permanente</strong></span></td><td><span class=\"kw-clinique\">Orifice anormal</span> (penser à la <strong><span class=\"kw-clinique\">fistule</span></strong>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>IU d'effort — 2 mécanismes (femme), souvent associés en proportion variable</strong></p>\n      <table >\n        <thead><tr><th></th><th>Hypermobilité cervico-urétrale</th><th>Insuffisance sphinctérienne</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalie</strong></td>\n            <td>Soutènement du col et de l'urètre <span class=\"kw-alerte\">déficient</span> (paroi antérieure du vagin)</td>\n            <td>Moyens d'occlusion de l'urètre <span class=\"kw-alerte\">déficients</span> (muqueuse, fibres lisses, sphincter strié)</td>\n          </tr>\n          <tr>\n            <td><strong>Manœuvre de soutènement</strong></td>\n            <td><span class=\"kw-clinique\">Corrige</span> la fuite ✅</td>\n            <td><span class=\"kw-alerte\">Ne corrige pas</span> la fuite ❌</td>\n          </tr>\n          <tr>\n            <td><strong>Chez l'homme</strong></td>\n            <td>N'existe pas</td>\n            <td>Seul mécanisme (10× plus rare) — surtout <span class=\"kw-alerte\">iatrogène</span> : prostatectomie totale, <span class=\"kw-ttt\">chirurgie</span> de l'HBP</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-alerte\">Urgence</span> mictionnelle (IUU) — contraction non contrôlée du détrusor</strong></p>\n      <p>S'intègre au <span class=\"kw-def\">syndrome clinique d'hyperactivité vésicale (SCHV)</span>. <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>roupes étiologiques :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Idiopathique</span> : anomalies urothélium / nerfs / détrusor, sans pathologie avérée.</li>\n        <li><span class=\"kw-etio\">Neurologique</span> : levée d'inhibition du réflexe mictionnel — <span class=\"kw-alerte\">AVC</span>, Parkinson, SEP, <span class=\"kw-clinique\">lésion</span> médullaire suprasacrée.</li>\n        <li><span class=\"kw-etio\">Psychologique</span> : système limbique (peur, anxiété, stress) — « la vessie est le miroir de l'âme ».</li>\n        <li><span class=\"kw-etio\">Causes locales</span> : à <strong>éliminer</strong> avant de poser le SCHV → irritation (infection, tumeur, calcul) ou obstruction sous-vésicale (HBP, prolapsus).</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>Distinction clé (piège QCM)</strong>\n        <ul>\n          <li><span class=\"kw-def\">Hyperactivité vésicale</span> = définition <strong>purement clinique</strong> (urgenturie).</li>\n          <li><span class=\"kw-def\">Hyperactivité détrusorienne</span> = contractions involontaires visibles <strong>seulement au bilan urodynamique</strong>.</li>\n          <li>Le SCHV n'est sous-tendu par une hyperactivité détrusorienne que dans <span class=\"kw-chiffre\">≈ 50 %</span> des cas.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 124 — Ménopause - andropause · 104 — <span class=\"kw-ttt\">Sclérose</span> en plaques · 105 — Mouvements anormaux (Parkinson)</em></p>","frequence":2},{"id":"125-7","rang":"B","rubrique":"Diagnostic","titre":"Connaître les signes d'alerte devant faire rechercher une cause grave d'incontinence","contenu":"<p>Même si l'IU est le plus souvent <em>le symptôme et la maladie à elle seule</em>, certains signes doivent faire rechercher une cause grave.</p>\n      <div class=\"callout callout-danger\">\n        <strong>🚩 <span class=\"kw-alerte\">Drapeaux rouges</span></strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Urgenturie associée</span> → éliminer une <span class=\"kw-etio\">infection</span>, une <span class=\"kw-etio\">tumeur de vessie ou de voisinage</span>, un <span class=\"kw-etio\">calcul</span> vésical / rétrovésical, voire un corps étranger intravésical.</li>\n          <li><span class=\"kw-alerte\">Suspicion d'origine neurologique</span> devant l'association : <strong>sujet jeune</strong> + <strong>installation brutale ou rapide</strong> de l'IU (quel que soit le type) + <strong>dysfonction sexuelle et anorectale</strong>.</li>\n          <li><span class=\"kw-alerte\">Hématurie macroscopique</span> associée → rechercher une <span class=\"kw-etio\">tumeur de vessie</span> ou une <span class=\"kw-etio\">infection urinaire</span>.</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 314 — Tumeurs de la vessie · 161 — Infections urinaires · 93 — Compression médullaire et <span class=\"kw-clinique\">syndrome de la</span> queue de cheval</em></p>","frequence":0},{"id":"125-8","rang":"A","rubrique":"Diagnostic","titre":"Connaître le bilan de première ligne d'une IU (après diagnostic quantification et retentissement)","contenu":"<div class=\"callout callout-warn\">\n        <strong>Triade du bilan de 1ʳᵉ intention (★★★ — à retenir absolument)</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Calendrier mictionnel</span> sur <span class=\"kw-chiffre\">72 h</span> — <strong>indispensable pour tous <span class=\"kw-clinique\">les</span> SBAU</strong>. Note : heure de chaque miction, volume uriné, survenue de fuite et circonstances.</li>\n          <li><span class=\"kw-bio\">ECBU</span> — élimine l'<span class=\"kw-clinique\">infection urinaire</span> et détecte une <span class=\"kw-bio\">hématurie</span> microscopique.</li>\n          <li><span class=\"kw-imagerie\">Échographie réno-vésicale et pelvienne</span> avec <strong>mesure du résidu post-mictionnel</strong>.</li>\n        </ul>\n      </div>\n      <p><strong>Examens de seconde ligne / orientés</strong> (non systématiques)</p>\n      <ul>\n        <li><span class=\"kw-bio\">Cytodiagnostic urinaire</span> : si <span class=\"kw-def\">facteur de risque</span> de tumeur de vessie et urgenturie.</li>\n        <li><span class=\"kw-imagerie\">Cystoscopie</span> : éliminer une tumeur de vessie / un calcul devant une urgenturie.</li>\n        <li><span class=\"kw-clinique\">Bilan urodynamique</span> : souvent <strong>avant traitement chirurgical</strong> ou dans <span class=\"kw-clinique\">les</span> formes complexes — <strong>non systématique</strong>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infections urinaires · 314 — Tumeurs de la vessie</em></p>","frequence":3},{"id":"125-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l'indication et l'apport des examens d'imagerie devant des troubles mictionnels, dysurie, incontinence urinaire","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indication / apport</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Échographie réno-vésicale et pelvienne</strong></span></td>\n            <td>Examen <strong>de 1ʳᵉ ligne</strong> : mesure du <span class=\"kw-clinique\">résidu post-mictionnel</span>, volume / morphologie prostatique, paroi vésicale (diverticules), retentissement haut appareil (urétéro-hydronéphrose), calcul, tumeur.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Débitmétrie libre</strong></span></td>\n            <td>Objective la dysurie : Qmax <span class=\"kw-chiffre\">&lt; 15 mL/s</span> → obstruction ; courbe aplatie = obstruction, polyphasique = hypocontractilité. Interprétable si volume + résidu <span class=\"kw-chiffre\">≥ 150 mL</span>. <strong>Ne différencie pas</strong> obstruction et hypocontractilité.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Urétrocystoscopie</strong></span></td>\n            <td>Localise un obstacle (sténose, adénome, tumeur) ; <strong>ne fait pas</strong> le diagnostic d'obstruction.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>UCRM</strong></span> (cystographie rétrograde et mictionnelle)</td>\n            <td>Peu de place : suspicion de <span class=\"kw-etio\">fistule urogénitale</span> ou d'obstacle sous-vésical / sténose non franchissable en <span class=\"kw-imagerie\">endoscopie</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM cérébrale + médullaire</strong></span></td>\n            <td>Si suspicion de <span class=\"kw-etio\">cause neurologique</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>IRM pelvienne</strong></span></td>\n            <td>Urgenturie + suspicion de tumeur pelvienne maligne ou bénigne (<span class=\"kw-etio\">endométriose</span>).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Bilan urodynamique</strong></span> (cystomanométrie)</td>\n            <td><strong>Seul examen</strong> renseignant sur la contraction vésicale et différenciant <span class=\"kw-etio\">obstruction</span> / <span class=\"kw-etio\">hypocontractilité</span> ; avant <span class=\"kw-ttt\">chirurgie</span> de l'IU, contexte neuro, IUU avant 2ⁿᵈ ligne.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Examens rares de 3ᵉ intention : imagerie neurologique (<span class=\"kw-imagerie\">IRM</span>) et électrophysiologie périnéale (<span class=\"kw-imagerie\">EMG</span> du sphincter strié) en contexte neurologique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 161 — Infections urinaires · 314 — Tumeurs de la vessie · 311 — Tumeurs du rein</em></p>","frequence":1},{"id":"125-10","rang":"B","rubrique":"Diagnostic","titre":"Connaître le bilan étiologique et les principes thérapeutiques d'une nycturie","contenu":"<p>La <span class=\"kw-def\"><strong>nycturie</strong></span> = fait d'être réveillé par l'envie d'uriner. Anormale dès le <span class=\"kw-chiffre\">1ᵉʳ lever</span> s'il entraîne une gêne. Chez le sujet âgé, elle expose aux <span class=\"kw-alerte\">chutes nocturnes</span> (fracture du col, hématome sous-dural).</p>\n      <div class=\"obj-callout success\">\n        <strong>Examen clé du bilan étiologique = le calendrier mictionnel +++</strong> — seul examen à distinguer, devant une nycturie, une <span class=\"kw-etio\">polyurie</span> d'une <span class=\"kw-etio\">pollakiurie nocturne</span>.\n      </div>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Bilan / orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Polyurie permanente</strong></span> (jour + nuit)</td>\n            <td>Trop d'urine sur <span class=\"kw-chiffre\">24 h</span>. Selon l'osmolalité urinaire : <span class=\"kw-chiffre\">&gt; 200-300 mOsm/kg</span> = diurèse osmotique (<span class=\"kw-etio\">diabète sucré</span> ++) ; <span class=\"kw-chiffre\">&lt; 200-300</span> = <span class=\"kw-etio\">diabète</span> insipide ou potomanie.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Polyurie nocturne</strong></span></td>\n            <td>Trop d'urine la nuit seulement (normalement <span class=\"kw-chiffre\">25 %</span> à<span class=\"kw-chiffre\"> 20-30 ans</span>, <span class=\"kw-chiffre\">33-35 %</span> après <span class=\"kw-chiffre\">65 ans</span>, par ↓ de l'ADH nocturne). Causes : boissons du soir, <span class=\"kw-ttt\">diurétique</span> vespéral, <span class=\"kw-clinique\">œdèmes</span> / <span class=\"kw-ci\">insuffisance cardiaque</span>, <span class=\"kw-etio\">SAHOS</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Pollakiurie nocturne isolée</strong></span></td>\n            <td>Perte de capacité vésicale fonctionnelle à diurèse constante. Bilan : calendrier mictionnel + <span class=\"kw-imagerie\">échographie</span> (résidu). Si urgenturie associée → éliminer infection / tumeur / calcul puis bilan de SCHV.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Principes thérapeutiques</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Règles hygiénodiététiques</span> : ↓ apports hydriques le soir, surélévation des jambes en journée si <span class=\"kw-clinique\">œdèmes</span>.</li>\n        <li>Nycturie par <span class=\"kw-clinique\">réduction de capacité vésicale</span> sans cause locale → traitement du SCHV (rééducation, anticholinergiques / β3-agonistes, neuromodulation, toxine botulique).</li>\n        <li>Nycturie par <span class=\"kw-clinique\">polyurie</span> sans cause : <span class=\"kw-ttt\">desmopressine</span> (ADH) le soir, si <span class=\"kw-chiffre\">&lt; 65 ans</span> + absence de potomanie → <strong>surveiller le risque d'hyponatrémie</strong>.</li>\n        <li>Si cause identifiée (SAOS, <span class=\"kw-ci\">insuffisance rénale</span> / cardiaque) → traiter la cause.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — <span class=\"kw-etio\">Diabète</span> · 264 — <span class=\"kw-ci\">Insuffisance rénale</span> chronique · 234 — Insuffisance cardiaque</em></p>","frequence":0},{"id":"125-11","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","contenu":"<p>La dysurie résulte de mécanismes pouvant s'associer, répartis en <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>rands groupes</strong>.</p>\n      <div class=\"callout callout-info\">\n        <strong>1. Hypocontractilité vésicale</strong> — <em>faiblesse du « moteur » de la miction</em>\n        <ul>\n          <li><span class=\"kw-etio\">Myogène</span> : destruction du muscle lisse — vieillissement, <span class=\"kw-ttt\">infiltration</span> amyloïde, obstruction chronique (« vessie claquée »).</li>\n          <li><span class=\"kw-etio\">Neurogène</span> : atteinte périphérique altérant l'innervation parasympathique (<strong>vessie neurologique périphérique</strong>).</li>\n          <li><span class=\"kw-alerte\">Médicamenteuse</span> : anticholinergiques (et antidépresseurs, antipsychotiques…), <span class=\"kw-ttt\">opiacés</span>.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>2a. Obstacles anatomiques de l'urètre</strong> — <em>filière de sortie bouchée — plus fréquent chez l'<strong>homme</strong></em>\n        <ul>\n          <li><span class=\"kw-etio\">Pariétal</span> : <strong>HBP ++++</strong> (homme &gt;<span class=\"kw-chiffre\"> 60 ans</span>), cancer de la prostate (avancé), sténose de l'urètre (urétrites, post-traumatique, carence hormonale chez la femme âgée), cystocèle, tumeur de l'urètre, bandelette sous-urétrale.</li>\n          <li><span class=\"kw-etio\">Luminal</span> : calcul enclavé dans l'urètre, caillotage vésical (<span class=\"kw-bio\">hématurie</span>, tumeur de vessie).</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>2b. Obstacles fonctionnels de l'urètre</strong> — <em>non-ouverture des sphincters — aussi fréquent H que F</em>\n        <ul>\n          <li><span class=\"kw-etio\">Dyssynergie vésico-sphinctérienne</span> : maladie neurologique (<span class=\"kw-clinique\">lésion</span> médullaire supra-sacrée — <strong>vessie neurologique centrale</strong>).</li>\n          <li><span class=\"kw-etio\">Asynchronisme vésico-sphinctérien / maladie du col vésical</span> : relaxation incomplète hors contexte neurologique.</li>\n          <li><span class=\"kw-alerte\">Hypertonie iatrogène</span> : médicaments <strong>α-stimulants</strong> (midodrine, vasoconstricteurs nasaux).</li>\n          <li><span class=\"kw-etio\">Syndrome de Fowler</span> (rare) : trouble de relaxation myogène, femme jeune + ovaires polykystiques.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-danger\">\n        <strong>Complications de la dysurie</strong> : rétention aiguë d'urine (complication aiguë), infections urinaires fébriles, <span class=\"kw-ci\">insuffisance rénale</span> (aiguë ou chronique).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeurs de la prostate · 50 — Pathologie génito-scrotale · 93 — Compression médullaire et <span class=\"kw-clinique\">syndrome de la</span> queue de cheval</em></p>","frequence":0},{"id":"125-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de traitement des principales étiologies de dysurie chez l'homme et chez la femme","contenu":"<p><strong>Prise en charge de l'hypocontractilité vésicale</strong></p>\n      <table >\n        <thead><tr><th>Ligne</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Auto-sondages propres intermittents</span></td></tr>\n          <tr><td><strong>2ⁿᵈ intention</strong></td><td>Sonde urétrale à demeure ou cathéter sus-pubien — <span class=\"kw-alerte\">non viables à long terme</span> (infections, destruction urétrale, cancérisation)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>À ne pas faire (pièges)</strong>\n        <ul>\n          <li><span class=\"kw-alerte\">Pas de traitement pharmacologique</span> de l'hypoactivité du détrusor (cholinergiques inefficaces et dangereux).</li>\n          <li><span class=\"kw-alerte\">Sphinctérotomie inefficace</span> (pas de moteur vésical pour vider).</li>\n        </ul>\n      </div>\n      <p><strong>Prise en charge des obstacles sous-vésicaux</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Obstacle prostatique</span> → prise en charge de l'<span class=\"kw-ttt\">HBP</span> ou du cancer de la prostate.</li>\n        <li><span class=\"kw-etio\">Sténose urétrale</span> → traitement chirurgical : <span class=\"kw-ttt\">urétrotomie endoscopique</span> ou <span class=\"kw-ttt\">urétroplastie</span> (résection-anastomose ou greffon, muqueuse buccale ++).</li>\n        <li><span class=\"kw-alerte\">Hypertonie médicamenteuse</span> → <strong>arrêt du médicament</strong> α-stimulant incriminé.</li>\n        <li><span class=\"kw-etio\">Dyssynergie</span> → α-bloquant (efficacité partielle) ; si sévère : auto-sondages, dérivation continente, voire Bricker.</li>\n        <li><span class=\"kw-etio\">Asynchronisme / syndrome de Fowler</span> → <span class=\"kw-ttt\">neuromodulation sacrée S3</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 310 — Tumeurs de la prostate · 50 — Pathologie génito-scrotale</em></p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>Nature :</strong> l'incontinence urinaire <span class=\"kw-etio\">altère la qualité de vie</span> mais <strong>ne <span class=\"kw-alerte\">menace</span> pas la survie</strong> ; la vraie <span class=\"kw-alerte\">urgence</span> est l'éventuelle <span class=\"kw-alerte\">rétention aiguë d'urine (RAU)</span>, complication aiguë du <span class=\"kw-etio\">syndrome dysurique</span>.<br><strong>1er geste :</strong> rechercher et lever un <span class=\"kw-clinique\">globe vésical</span> (capacité vésicale normale <span class=\"kw-chiffre\">300–500 mL</span>, jusqu'à <span class=\"kw-chiffre\">500–1000 mL</span> en cas de RAU).<br><strong>Sujet âgé :</strong> toute <span class=\"kw-clinique\">confusion</span> ou agitation doit faire <strong>éliminer une RAU</strong> se révélant par une <span class=\"kw-etio\">IU par regorgement</span> (D de DIAPPERS).<br><strong>Enfant :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">valves de l'urètre postérieur</span> (garçon) sont une <span class=\"kw-alerte\">urgence médico-chirurgicale</span> → <span class=\"kw-ttt\">résection endoscopique des valves</span>.</p>","hospit":"<p><strong>Cadre :</strong> prise en charge <strong>ambulatoire</strong> dans la très grande majorité des cas.<br><strong>Avis spécialisé :</strong> l'urologue oriente vers le spécialiste concerné selon la cause — appareillage d'un <span class=\"kw-etio\">SAOS</span>, prise en charge d'une <span class=\"kw-etio\">insuffisance rénale</span> ou <span class=\"kw-etio\">cardiaque</span>.<br><strong>Suspicion neurologique :</strong> évaluation spécialisée + <span class=\"kw-imagerie\">IRM cérébrale et médullaire</span>.<br><strong>Enfant :</strong> <strong>avis spécialisé</strong> si <span class=\"kw-etio\">hyperactivité détrusorienne neurologique</span> ou <span class=\"kw-etio\">valves de l'urètre postérieur</span>.</p>","redflags":"<ul><li><span class=\"kw-clinique\">Urgenturie</span> associée → toujours éliminer une <span class=\"kw-etio\">infection urinaire</span>, une <span class=\"kw-etio\">tumeur de vessie ou de voisinage</span>, un <span class=\"kw-etio\">calcul vésical ou rétrovésical</span>, voire un <span class=\"kw-etio\">corps étranger intravésical</span>.</li><li><span class=\"kw-clinique\">Hématurie macroscopique</span> associée → rechercher une <span class=\"kw-etio\">tumeur de vessie</span> ou une <span class=\"kw-etio\">infection urinaire</span>.</li><li>Suspicion d'origine <span class=\"kw-etio\">neurologique</span> : association <span class=\"kw-clinique\">sujet jeune</span> + <span class=\"kw-clinique\">installation brutale ou rapide</span> de l'IU + <span class=\"kw-clinique\">dysfonction sexuelle et anorectale</span>.</li><li>Complications du <span class=\"kw-etio\">syndrome dysurique</span> : <span class=\"kw-alerte\">rétention aiguë d'urine</span>, <span class=\"kw-etio\">infections urinaires fébriles</span>, <span class=\"kw-alerte\">insuffisance rénale aiguë ou chronique</span>.</li><li>Enfant — signes d'alerte d'une <span class=\"kw-etio\">cause neurologique</span> : <span class=\"kw-clinique\">stigmate cutané dorsolombaire</span> (lipome, angiome, touffe de poils), anomalies de la <span class=\"kw-clinique\">motricité des membres inférieurs</span>, <span class=\"kw-clinique\">pied creux / scoliose</span>.</li></ul>","principes":"<p>La prise en charge découle du <strong>type de trouble</strong> et de son <span class=\"kw-etio\">mécanisme</span> ; un <span class=\"kw-ttt\">calendrier mictionnel sur 72 h</span> et l'<span class=\"kw-imagerie\">échographie avec mesure du résidu post-mictionnel</span> orientent toutes <span class=\"kw-clinique\">les</span> décisions.</p><p><strong>Bilan de 1ʳᵉ ligne d'une incontinence</strong></p><p><span class=\"kw-imagerie\">Bilan urodynamique</span> et <span class=\"kw-imagerie\">cystoscopie</span> : 2ᵉ intention (avant <span class=\"kw-ttt\">chirurgie</span>, contexte neurologique, échec du traitement de 1ʳᵉ ligne).</p><ul><li><span class=\"kw-ttt\">Calendrier mictionnel</span> sur <span class=\"kw-chiffre\">72 h</span> : <strong>indispensable pour tous <span class=\"kw-clinique\">les</span> SBAU</strong>.</li><li><span class=\"kw-bio\">ECBU</span> : éliminer une <span class=\"kw-etio\">infection urinaire</span>, détecter une <span class=\"kw-clinique\">hématurie</span> microscopique.</li><li><span class=\"kw-imagerie\">Échographie réno-vésico-pelvienne</span> avec <strong>mesure du résidu post-mictionnel</strong>.</li></ul><p><strong>IU d'effort (cible = urètre)</strong></p><p>Chez la femme, traiter aussi l'<span class=\"kw-etio\">obésité</span> et la <span class=\"kw-etio\">carence hormonale</span> (<span class=\"kw-ttt\">oestrogénothérapie vaginale</span>).</p><ul><li><strong>Pas de traitement <span class=\"kw-etio\">médicamenteux</span></strong> ❌ pour l'IU d'effort.</li><li>1ʳᵉ ligne : <span class=\"kw-ttt\">rééducation périnéo-sphinctérienne</span> (renforcement du <span class=\"kw-ttt\">levator ani</span>).</li><li><span class=\"kw-clinique\">Test de soutènement urétral</span> : prédit l'efficacité d'une <span class=\"kw-ttt\">bandelette sous-urétrale</span>.</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">bandelette sous-urétrale</span> (TVT/TOT), <span class=\"kw-ttt\">ballons ajustables</span>, <span class=\"kw-ttt\">sphincter urinaire artificiel</span>.</li></ul><p><strong>IU par urgenturie / SCHV (cible = vessie)</strong></p><p><span class=\"kw-ci\">Glaucome aigu à angle fermé</span> = CI des anticholinergiques ; <span class=\"kw-ci\">HTA non équilibrée</span> = CI du <span class=\"kw-ttt\">mirabégron</span>.</p><ul><li>Pré-requis : <strong>éliminer une cause locale</strong> (<span class=\"kw-etio\">infection</span>, <span class=\"kw-etio\">tumeur</span>, <span class=\"kw-etio\">calcul</span>, <span class=\"kw-etio\">obstruction sous-vésicale</span>) avant de retenir le diagnostic.</li><li>1ʳᵉ ligne : mesures générales (<span class=\"kw-ttt\">rééducation</span>) + <span class=\"kw-ttt\">anticholinergiques</span> (anti-muscariniques <span class=\"kw-chiffre\">M1</span>–M3) ou <span class=\"kw-ttt\">β3-agonistes</span> (<span class=\"kw-ttt\">mirabégron</span>).</li><li>2ᵉ ligne : <span class=\"kw-ttt\">neuromodulation du nerf sacré S3</span> ou du <span class=\"kw-ttt\">nerf tibial postérieur</span>, <span class=\"kw-ttt\">toxine botulique A intravésicale</span>.</li><li>3ᵉ ligne (atteinte sévère) : <span class=\"kw-ttt\">entérocystoplastie d'agrandissement</span>.</li></ul><p><strong>Dysurie : hypocontractilité vésicale</strong></p><ul><li>1ʳᵉ intention : <span class=\"kw-ttt\">auto-sondages propres intermittents</span>.</li><li><strong>Pas de traitement pharmacologique</strong> ❌ de l'hypoactivité du détrusor (cholinergiques inefficaces et dangereux).</li><li><span class=\"kw-ttt\">Sphinctérotomie inefficace</span> ❌ (pas de moteur vésical pour vider).</li></ul><p><strong>Dysurie : obstacle sous-vésical</strong></p><ul><li>Obstacle prostatique : prise en charge de l'<span class=\"kw-etio\">HBP</span> ou du <span class=\"kw-etio\">cancer de la prostate</span>.</li><li><span class=\"kw-etio\">Sténose urétrale</span> : <span class=\"kw-ttt\">urétrotomie endoscopique</span> ou <span class=\"kw-ttt\">urétroplastie</span>.</li><li>Hypertonie <span class=\"kw-etio\">iatrogène</span> : <strong>arrêt</strong> du médicament <span class=\"kw-ttt\">α-stimulant</span> incriminé.</li></ul><p><strong>Nycturie</strong></p><ul><li><span class=\"kw-ttt\">Calendrier mictionnel</span> = examen clé : distingue <span class=\"kw-etio\">polyurie</span> et <span class=\"kw-etio\">pollakiurie nocturne</span>.</li><li><span class=\"kw-ttt\">Règles hygiéno-diététiques</span> : <strong><span class=\"kw-ttt\">réduction</span> des apports hydriques le soir</strong>, surélévation des jambes si <span class=\"kw-clinique\">œdèmes des membres inférieurs</span>.</li><li><span class=\"kw-ttt\">Desmopressine</span> (substitut d'<span class=\"kw-def\">hormone antidiurétique</span>) si <span class=\"kw-chiffre\">&lt; 65 ans</span> + <strong>absence de potomanie</strong> — surveiller l'<span class=\"kw-etio\">hyponatrémie</span>.</li></ul>","suivi":"<p><strong>Outil de <span class=\"kw-def\">suivi</span> :</strong> le <span class=\"kw-ttt\">calendrier mictionnel</span> quantifie l'<span class=\"kw-clinique\">évolution</span> (nombre de mictions, fuites, diurèse jour/nuit).<br><strong>Mictions programmées :</strong> à intervalles réguliers, <span class=\"kw-chiffre\">toutes les 4 h</span> (sauf la nuit), en cas d'IU du sujet âgé / fonctionnelle.<br><strong>Sous desmopressine :</strong> surveiller étroitement le risque d'<span class=\"kw-etio\">hyponatrémie</span>.<br><strong>Sous anticholinergiques :</strong> surveiller <span class=\"kw-clinique\">bouche sèche</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">confusion</span> du sujet âgé, <span class=\"kw-clinique\">trouble du rythme</span> si QT long.</p>"},"liensGlobaux":[{"href":"https://www.urofrance.org/lafu-academie/formation-du-college/referentiel-du-college-durologie-6eme-edition/chapitre-8-item-125-troubles-de-la-miction-et-incontinence-urinaire-de-ladulte-et-du-sujet-age/","label":"Collège d'Urologie — chapitre 8 (item 125)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Incontinence urinaire confirmée — Fuite involontaire d'urine — diagnostic clinique (voir la fuite). Bilan 1ʳᵉ ligne : calendrier mictionnel 72 h + ECBU + échographie avec résidu post-mictionnel.","detail":"<h4>CAT — Incontinence urinaire : orientation diagnostique — Démarche devant une fuite involontaire d'urine (diagnostic clinique)</h4>","branches":[{"to":"q-redflags","label":"Évaluer","color":"blue"}]},{"id":"q-redflags","kind":"decision","label":"Signe d'alerte de cause grave ? — Hématurie macroscopique · urgenturie · sujet jeune + début brutal + dysfonction sexuelle/anorectale","branches":[{"to":"t-grave","label":"Oui","color":"red"},{"to":"q-age","label":"Non","color":"green"}]},{"id":"t-grave","kind":"terminal","label":"Bilan étiologique d'une cause grave","color":"red","detail":"<h4>Conduite</h4><ul><li>Éliminer une <span class=\"kw-etio\">tumeur de vessie ou de voisinage</span>, une <span class=\"kw-etio\">infection urinaire</span>, un <span class=\"kw-etio\">calcul</span> ou une <span class=\"kw-etio\">cause neurologique</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">ECBU</span> ± <span class=\"kw-bio\">cytologie urinaire</span> (si FR de tumeur + urgenturie).</li><li><span class=\"kw-imagerie\">Échographie vésicale</span> + <span class=\"kw-imagerie\">urétrocystoscopie</span> si urgenturie / FR <span class=\"kw-etio\">tumoral</span>.</li><li><span class=\"kw-imagerie\">IRM cérébrale et médullaire</span> si suspicion de <span class=\"kw-etio\">cause neurologique</span>.</li></ul>"},{"id":"q-age","kind":"decision","label":"Sujet âgé (≥ 75 ans) ?","branches":[{"to":"q-rau","label":"Oui (≥ 75 ans)","color":"amber"},{"to":"q-type","label":"Non","color":"blue"}]},{"id":"q-rau","kind":"decision","label":"Globe vésical / suspicion de rétention ?","branches":[{"to":"t-rau","label":"Globe palpable / RPM > 300 mL","color":"red"},{"to":"t-diappers","label":"Pas de globe","color":"amber"}]},{"id":"t-rau","kind":"terminal","label":"Lever la rétention aiguë d'urine","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">IU par regorgement</span> : <span class=\"kw-clinique\">vessie palpable et indolore</span> après la miction, <span class=\"kw-chiffre\">résidu post-mictionnel > 300 mL</span>.</li><li>Capacité vésicale normale <span class=\"kw-chiffre\">300–500 mL</span>, jusqu'à <span class=\"kw-chiffre\">500–1000 mL</span> en cas de RAU.</li></ul><h4>Conduite</h4><ul><li><strong>Éliminer et lever</strong> la <span class=\"kw-alerte\">rétention aiguë d'urine</span> avant tout autre bilan (1ʳᵉ étape de la démarche du sujet âgé).</li><li>Une fois la rétention levée : dérouler l'acronyme <span class=\"kw-ttt\">DIAPPERS</span> (IU transitoire réversible).</li></ul>"},{"id":"t-diappers","kind":"terminal","label":"Rechercher une IU transitoire réversible (DIAPPERS)","color":"amber","detail":"<h4>Conduite</h4><ul><li>Acronyme <span class=\"kw-ttt\">DIAPPERS</span> : <span class=\"kw-etio\">Délirium</span>, <span class=\"kw-etio\">Infection urinaire</span>, <span class=\"kw-etio\">Atrophie vaginale</span>, Psychologique, Pharmacologique, Excès de diurèse, Restriction de mobilité, Selles (<span class=\"kw-clinique\">constipation</span>).</li><li>Cause réversible → traitement étiologique ; sinon <span class=\"kw-etio\">IU non réversible</span> → même prise en charge que chez le sujet jeune (IU urgenturie et mixte plus fréquentes).</li></ul>"},{"id":"q-type","kind":"decision","label":"Caractéristiques de la fuite ? — Oriente le type d'incontinence et la prise en charge","branches":[{"to":"t-iue","label":"À l'effort, sans besoin","color":"green"},{"to":"t-iuu","label":"Précédée d'urgenturie","color":"amber"},{"to":"t-mixte","label":"Effort + urgenturie","color":"amber"}]},{"id":"t-iue","kind":"terminal","label":"IU d'effort → rééducation ± chirurgie","color":"green","detail":"<h4>Clinique</h4><ul><li>Fuite à l'<span class=\"kw-clinique\">effort</span> (<span class=\"kw-clinique\">toux</span>, port de charge), <span class=\"kw-clinique\">jet non précédé de besoin</span>, arrêt au repos.</li><li><span class=\"kw-clinique\">Test de soutènement urétral</span> (femme) : positif si la fuite disparaît → prédit l'efficacité d'une <span class=\"kw-ttt\">bandelette sous-urétrale</span>.</li></ul><h4>Traitement</h4><ul><li><strong>Pas de traitement <span class=\"kw-etio\">médicamenteux</span></strong> ❌.</li><li>1ʳᵉ ligne : <span class=\"kw-ttt\">rééducation périnéo-sphinctérienne</span> (levator ani).</li><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">bandelette sous-urétrale</span>, <span class=\"kw-ttt\">ballons ajustables</span>, <span class=\"kw-ttt\">sphincter urinaire artificiel</span>.</li></ul>"},{"id":"t-iuu","kind":"terminal","label":"IU par urgenturie / SCHV","color":"amber","detail":"<h4>Clinique</h4><ul><li>Fuite précédée / accompagnée d'une <span class=\"kw-clinique\">urgenturie</span>, à n'importe quel moment (effort, repos, jour, nuit).</li></ul><h4>Conduite</h4><ul><li><strong>Éliminer d'abord</strong> une <span class=\"kw-etio\">cause locale</span> (infection, tumeur, calcul, obstruction sous-vésicale).</li><li>1ʳᵉ ligne : <span class=\"kw-ttt\">anticholinergiques</span> ou <span class=\"kw-ttt\">β3-agonistes</span> ; 2ᵉ ligne : <span class=\"kw-ttt\">neuromodulation S3</span> / <span class=\"kw-ttt\">toxine botulique A</span>.</li><li>CI : <span class=\"kw-ci\">glaucome aigu à angle fermé</span> (anticholinergiques), <span class=\"kw-ci\">HTA non équilibrée</span> (mirabégron).</li></ul>"},{"id":"t-mixte","kind":"terminal","label":"IU mixte → traiter la composante prédominante","color":"amber","detail":"<h4>Conduite</h4><ul><li>IU mixte = <span class=\"kw-etio\">effort</span> + <span class=\"kw-etio\">urgenturie</span> : identifier la <strong>composante prédominante</strong> et la traiter en premier.</li></ul>"}]},"cards":[{"i":"23eb6a9f7cf1","n":125,"o":"125-1","u":"Diagnostic positif","t":"Connaître la définition des symptômes du bas appareil urinaire SBAU (= LUTS anglosaxon) (examen clinique, démarche diagnostique)","q":"Quels sont les principaux symptômes de la phase de vidange (mictionnelle) et post-mictionnelle dans les SBAU ?","a":"<ul><li><strong>Brûlures mictionnelles</strong> : sensations de brûlure ressenties dans l'urètre au passage de l'urine.</li><li><strong>Syndrome dysurique (dysurie)</strong> : comprend un ou plusieurs des signes suivants : <strong>retard au démarrage</strong>, <strong>nécessité de pousser</strong>, <strong>jet faible</strong> et/ou <strong>en arrosoir</strong>, <strong>jet interrompu</strong>, <strong>miction en plusieurs temps</strong>.</li><li><strong>Gouttes retardataires</strong> (post-mictionnelles).</li><li><strong>Sensation de vidange incomplète</strong> (post-mictionnelle, peut s'intégrer au syndrome dysurique).</li></ul>"},{"i":"5096dc8d81fe","n":125,"o":"125-1","u":"Diagnostic positif","t":"Connaître la définition des symptômes du bas appareil urinaire SBAU (= LUTS anglosaxon) (examen clinique, démarche diagnostique)","q":"Quels sont les principaux symptômes de la phase de stockage ou de remplissage dans les SBAU ?","a":"<ul><li><strong>Incontinence urinaire</strong> : fuite involontaire d'urine.</li><li><strong>Énurésie</strong> : miction complète involontaire nocturne ou diurne lors d'un paroxysme émotionnel.</li><li><strong>Pollakiurie</strong> : augmentation du nombre de mictions à diurèse constante (<strong>≥ 8 mictions/24 h</strong> le jour, ou nocturne dès <strong>≥ 1 lever</strong> gênant).</li><li><strong>Nycturie</strong> : être réveillé par l'envie d'uriner (anormale dès le <strong>1er lever</strong> s'il entraîne une gêne).</li><li><strong>Urgenturie</strong> : désir soudain, impérieux et irrépressible d'uriner.</li><li><strong>Syndrome Clinique d'Hyperactivité Vésicale (SCHV)</strong> : centré sur l'urgenturie (sa seule présence suffit), associée ou non à <strong>pollakiurie</strong>, <strong>nycturie</strong> ou <strong>incontinence</strong>.</li></ul>"},{"i":"a542e4fa8aef","n":125,"o":"125-1","u":"Diagnostic positif","t":"Connaître la définition des symptômes du bas appareil urinaire SBAU (= LUTS anglosaxon) (examen clinique, démarche diagnostique)","q":"Quelle est la définition des Symptômes du Bas Appareil Urinaire (SBAU, ou LUTS) ?","a":"<p>Les Symptômes du Bas Appareil Urinaire (SBAU) sont des manifestations cliniques liées au mauvais fonctionnement de la vessie, de l'urètre ou des sphincters. Ils englobent les symptômes de <strong>stockage</strong>, de <strong>vidange</strong> et <strong>post-mictionnels</strong>. Il faut les rechercher systématiquement à l'interrogatoire, même si un seul est prédominant.</p>"},{"i":"229be5049eeb","n":125,"o":"125-11","u":"Étiologies","t":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","q":"Quels mécanismes principaux sont à l'origine de la dysurie, chez l'homme comme chez la femme ?","a":"<p>La dysurie résulte de mécanismes pouvant s'associer et se répartit en deux grands groupes :</p><ul><li>Une <strong>hypocontractilité vésicale</strong> (faiblesse du « moteur » de la miction).</li><li>Des <strong>obstacles urétraux</strong>, qui peuvent être anatomiques ou fonctionnels.</li></ul>"},{"i":"3d9aaf3f43ce","n":125,"o":"125-11","u":"Étiologies","t":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","q":"Quelles sont les étiologies des obstacles fonctionnels de l'urètre, pouvant provoquer une dysurie chez l'homme et la femme ?","a":"<p>Les obstacles fonctionnels de l'urètre, aussi fréquents chez l'homme que chez la femme, sont :</p><ul><li>La <strong>dyssynergie vésico-sphinctérienne</strong> : en cas de maladie neurologique (lésion médullaire supra-sacrée — vessie neurologique centrale).</li><li>L'<strong>asynchronisme vésico-sphinctérien</strong> / maladie du col vésical : relaxation incomplète hors contexte neurologique.</li><li>L'<strong>hypertonie iatrogène</strong> : médicaments α-stimulants (midodrine, vasoconstricteurs nasaux).</li><li>Le <strong>syndrome de Fowler</strong> (rare) : trouble de relaxation myogène, souvent chez la femme jeune avec ovaires polykystiques.</li></ul>"},{"i":"6fe7b6e8db0c","n":125,"o":"125-11","u":"Étiologies","t":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","q":"Quelles sont les complications possibles d'une dysurie non prise en charge ?","a":"<p>Les complications de la dysurie incluent :</p><ul><li>La <strong>rétention aiguë d'urine</strong> (complication aiguë).</li><li>Les <strong>infections urinaires fébriles</strong>.</li><li>L'<strong>insuffisance rénale</strong> (aiguë ou chronique).</li></ul>"},{"i":"a39984bcf91b","n":125,"o":"125-11","u":"Étiologies","t":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","q":"Quelles sont les causes d'hypocontractilité vésicale pouvant mener à une dysurie ?","a":"<p>Les causes d'hypocontractilité vésicale (faiblesse du « moteur ») incluent :</p><ul><li>Des atteintes <strong>myogènes</strong> : destruction du muscle lisse (vieillissement, infiltration amyloïde, obstruction chronique type « vessie claquée »).</li><li>Des atteintes <strong>neurogènes</strong> : atteinte périphérique par altération de l'innervation parasympathique (vessie neurologique périphérique).</li><li>Des causes <strong>médicamenteuses</strong> : anticholinergiques (et antidépresseurs, antipsychotiques), opiacés.</li></ul>"},{"i":"fa960109244e","n":125,"o":"125-11","u":"Étiologies","t":"Connaître les principales étiologies de la dysurie de l'homme et de la femme","q":"Quelles sont les étiologies des obstacles anatomiques de l'urètre, plus fréquents chez l'homme, pouvant provoquer une dysurie ?","a":"<p>Les obstacles anatomiques de l'urètre, plus fréquents chez l'homme, peuvent être :</p><ul><li><strong>Pariétaux</strong> : <ul><li><strong>Hypertrophie Bénigne de la Prostate (HBP) ++++</strong> (homme > 60 ans).</li><li>Cancer de la prostate (avancé).</li><li>Sténose de l'urètre (urétrites, post-traumatique, carence hormonale chez la femme âgée).</li><li>Cystocèle, tumeur de l'urètre, bandelette sous-urétrale.</li></ul></li><li><strong>Luminaux</strong> : <ul><li>Calcul enclavé dans l'urètre.</li><li>Caillotage vésical (hématurie, tumeur de vessie).</li></ul></li></ul>"},{"i":"0e7175f6a7d7","n":125,"o":"125-2","u":"Définition","t":"Connaître la définition de l'incontinence urinaire","q":"Quel est l'impact principal de l'incontinence urinaire sur le patient ?","a":"<p>L'incontinence urinaire est un problème <p>social ou d'hygiène</p> qui altère profondément la <p>qualité de vie</p> du patient, sans pour autant menacer sa survie.</p>"},{"i":"6004c488642f","n":125,"o":"125-2","u":"Définition","t":"Connaître la définition de l'incontinence urinaire","q":"Quelle est la définition de l'incontinence urinaire ?","a":"<p>L'incontinence urinaire est une <p>perte involontaire d'urine</p>."},{"i":"38f0f5fd2559","n":125,"o":"125-8","u":"Diagnostic","t":"Connaître le bilan de première ligne d'une IU (après diagnostic quantification et retentissement)","q":"Quel examen d'imagerie est inclus dans le bilan de première ligne d'une incontinence urinaire ?","a":"<p>Une <strong>échographie réno-vésicale et pelvienne</strong> est réalisée, avec une mesure systématique du <strong>résidu post-mictionnel</strong>.</p>"},{"i":"782e48a91944","n":125,"o":"125-8","u":"Diagnostic","t":"Connaître le bilan de première ligne d'une IU (après diagnostic quantification et retentissement)","q":"Quelle est la première étape du bilan de première ligne d'une incontinence urinaire, notamment concernant les symptômes du bas appareil urinaire (SBAU) ?","a":"<p>La première étape est la réalisation d'un <strong>calendrier mictionnel</strong> sur <strong>72 heures</strong>. C'est un examen indispensable pour tous les SBAU.</p>"},{"i":"ba3d1b8889e6","n":125,"o":"125-8","u":"Diagnostic","t":"Connaître le bilan de première ligne d'une IU (après diagnostic quantification et retentissement)","q":"Quelles informations clés doit contenir un calendrier mictionnel dans le cadre de l'évaluation d'une incontinence urinaire ?","a":"<p>Un calendrier mictionnel doit noter :</p><ul><li>L'heure de chaque miction.</li><li>Le volume uriné à chaque miction.</li><li>La survenue de fuites urinaires et leurs circonstances.</li></ul>"},{"i":"ee4ddb669fb0","n":125,"o":"125-8","u":"Diagnostic","t":"Connaître le bilan de première ligne d'une IU (après diagnostic quantification et retentissement)","q":"Quel examen biologique est systématiquement réalisé dans le bilan de première ligne d'une incontinence urinaire ?","a":"<p>Un <strong>Examen CytoBactériologique des Urines (ECBU)</strong> est systématiquement réalisé pour éliminer une <strong>infection urinaire</strong> et détecter une éventuelle <strong>hématurie microscopique</strong>.</p>"}]};